def column_sums(grid):
    if not grid or not grid[0]:
        return []
    return [sum(row[c] for row in grid) for c in range(len(grid[0]))]

def count_value_neighbours(grid, r, c, value):
    rows = len(grid)
    count = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows:
            cols = len(grid[nr])
            if 0 <= nc < cols and grid[nr][nc] == value:
                count += 1
    return count

def main_diagonal(grid):
    if not grid or not grid[0]:
        return []
    n = min(len(grid), len(grid[0]))
    return [grid[i][i] for i in range(n)]

def anti_diagonal(grid):
    if not grid or not grid[0]:
        return []
    cols = len(grid[0])
    n = min(len(grid), cols)
    return [grid[i][cols - 1 - i] for i in range(n)]

def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    top, bottom = 0, len(grid) - 1
    left, right = 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            result.append(grid[top][c])
        top += 1
        for r in range(top, bottom + 1):
            result.append(grid[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(grid[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(grid[r][left])
            left += 1
    return result

def border_elements(grid):
    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])
    result = []
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                result.append(grid[r][c])
    return result

def equal_under_rotation(grid1, grid2):
    def rotate90(g):
        return [list(row) for row in zip(*g[::-1])]

    current = [list(row) for row in grid1]
    for _ in range(4):
        if current == grid2:
            return True
        current = rotate90(current)
