def flatten_grid(grid):
    result = []
    for row in grid:
        result.extend(row)
    return result

def max_value_position(grid):
    best_val = None
    best_pos = None
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if best_val is None or val > best_val:
                best_val = val
                best_pos = (r, c)
    return best_pos

def row_with_max_sum(grid):
    best_idx = 0
    best_sum = sum(grid[0])
    for i in range(1, len(grid)):
        s = sum(grid[i])
        if s > best_sum:
            best_sum = s
            best_idx = i
    return best_idx

def column_with_max_sum(grid):
    cols = len(grid[0])
    sums = [sum(row[c] for row in grid) for c in range(cols)]
    best_idx = 0
    best_sum = sums[0]
    for i in range(1, cols):
        if sums[i] > best_sum:
            best_sum = sums[i]
            best_idx = i
    return best_idx

def diagonal_sum_total(grid):
    n = len(grid)
    total = 0
    for i in range(n):
        total += grid[i][i]
        total += grid[i][n - 1 - i]
    if n % 2 == 1:
        mid = n // 2
        total -= grid[mid][mid]
    return total

def count_paths(grid):
    rows = len(grid)
    cols = len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1
    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                continue
            if grid[r][c] == 1:
                dp[r][c] = 0
                continue
            top = dp[r - 1][c] if r > 0 else 0
            left = dp[r][c - 1] if c > 0 else 0
            dp[r][c] = top + left
    return dp[rows - 1][cols - 1]
